(15119,0,0,'You can go home now. I\'ll cover your back.',68580,1,1,0,0,0,0,NULL,0,0),
(60007,0,0,'Take the item from his hand.',64110,1,1,0,0,0,0,NULL,0,0),
(60010,0,0,'I challenge you!',62248,1,1,0,0,0,0,NULL,0,0),
(60011,0,0,'I challenge you!',62248,1,1,0,0,0,0,NULL,0,0),
(60012,0,0,'I challenge you!',62248,1,1,0,0,0,0,NULL,0,0),
